cd /home/****/code/req-squad/workspace/6343a752-e110-407c-8dfb-a5873425d917
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -N -e "
SELECT 'tables',COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE();
SELECT 'dishes',COUNT(*) FROM dishes;
SELECT 'option_groups',COUNT(*) FROM dish_option_groups;
SELECT 'options',COUNT(*) FROM dish_options;
SELECT 'menu_today',COUNT(*) FROM daily_menu WHERE serve_date=CURDATE();
SELECT 'stock_today',COUNT(*) FROM dish_daily_stock WHERE serve_date=CURDATE();
SELECT 'stock_future',COUNT(*) FROM dish_daily_stock WHERE serve_date>CURDATE();
INSERT INTO orders(order_no,user_id,status,delivery_date,meal_type,address,total_cents,item_count,idempotency_key,snapshot_json)
VALUES('WB20261114-0001',2,'Pending',CURDATE(),'Lunch','A',100,1,'k1','{}');
SELECT 'active_key1',active_key FROM orders WHERE order_no='WB20261114-0001';
" 2>&1 | grep -v 'Using a password'
echo '--- unique active test (expect 1062) ---'
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -e "
INSERT INTO orders(order_no,user_id,status,delivery_date,meal_type,address,total_cents,item_count,idempotency_key,snapshot_json)
VALUES('WB20261114-0002',2,'Confirmed',CURDATE(),'Lunch','A',100,1,'k2','{}');" 2>&1 | grep -v 'Using a password'
echo '--- cancel then reorder (expect success, active_key NULL then new order ok) ---'
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -e "
UPDATE orders SET status='Cancelled' WHERE order_no='WB20261114-0001';
INSERT INTO orders(order_no,user_id,status,delivery_date,meal_type,address,total_cents,item_count,idempotency_key,snapshot_json)
VALUES('WB20261114-0003',2,'Pending',CURDATE(),'Lunch','A',100,1,'k3','{}');
SELECT order_no,status,active_key FROM orders ORDER BY id;" 2>&1 | grep -v 'Using a password'
echo '--- stock guard (expect check violation) ---'
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -e "
UPDATE dish_daily_stock SET reserved_qty=total_qty+1 WHERE dish_id=1 AND serve_date=CURDATE();" 2>&1 | grep -v 'Using a password'

cd /home/****/code/req-squad/workspace/6343a752-e110-407c-8dfb-a5873425d917
{
echo "# Architecture DDL check evidence $(date '+%F %T %Z')"
echo "## MySQL version"; mysql -h127.0.0.1 -utest -ptest123456 -N -e "SELECT VERSION();" 2>/dev/null
echo "## schema.sql applied to scratch db req_6343a752e110_ddlcheck: no errors"
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -N -e "
SELECT CONCAT('tables=',COUNT(*)) FROM information_schema.tables WHERE table_schema=DATABASE();
SELECT CONCAT('dishes=',COUNT(*)) FROM dishes;
SELECT CONCAT('option_groups=',COUNT(*)) FROM dish_option_groups;
SELECT CONCAT('options=',COUNT(*)) FROM dish_options;
SELECT CONCAT('menu_today=',COUNT(*)) FROM daily_menu WHERE serve_date=CURDATE();
SELECT CONCAT('stock_today=',COUNT(*)) FROM dish_daily_stock WHERE serve_date=CURDATE();
SELECT CONCAT('stock_future=',COUNT(*)) FROM dish_daily_stock WHERE serve_date>CURDATE();
SELECT CONCAT('active_key=',active_key) FROM orders WHERE order_no='WB20261114-0001';
" 2>/dev/null
echo "## duplicate active order -> expect 1062"
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -e "INSERT INTO orders(order_no,user_id,status,delivery_date,meal_type,address,total_cents,item_count,idempotency_key,snapshot_json) VALUES('WB20261114-0002',2,'Confirmed',CURDATE(),'Lunch','A',100,1,'k2','{}');" 2>&1 | grep -v 'Using a password'
echo "## stock over-allocation -> expect 3819"
mysql -h127.0.0.1 -utest -ptest123456 req_6343a752e110_ddlcheck -e "UPDATE dish_daily_stock SET reserved_qty=total_qty+1 WHERE dish_id=1 AND serve_date=CURDATE();" 2>&1 | grep -v 'Using a password'
echo "## cleanup scratch database"
mysql -h127.0.0.1 -utest -ptest123456 -e "DROP DATABASE req_6343a752e110_ddlcheck;" 2>/dev/null && echo "dropped"
} > artifacts/architecture-ddl-check.txt 2>&1
cat artifacts/architecture-ddl-check.txt; echo '---'; wc -l docs/architecture.md docs/api-contract.md docs/data-model.md docs/cross-review-g1.md docs/review-findings.md docs/schema.sql
